-- PricePilot Canada initial schema. Apply only to a dedicated, approved Supabase project.
create extension if not exists pg_trgm;
create table public.retailers(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,website_url text,logo_url text,status text not null default 'inactive' check(status in ('active','inactive','suspended')),created_at timestamptz not null default now());
create table public.retailer_stores(id uuid primary key default gen_random_uuid(),retailer_id uuid not null references public.retailers(id),external_id text,name text not null,address text,city text,province text,postal_code text,latitude numeric(10,7),longitude numeric(10,7),active boolean not null default true,unique(retailer_id,external_id));
create table public.data_sources(id uuid primary key default gen_random_uuid(),retailer_id uuid references public.retailers(id),provider text not null,source_type text not null,authorization_status text not null default 'pending' check(authorization_status in ('pending','authorized','restricted','expired','revoked','blocked')),license_reference text,license_expires_at timestamptz,allowed_redistribution boolean not null default false,allowed_images boolean not null default false,last_success_at timestamptz,created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),parent_id uuid references public.categories(id),name text not null,slug text not null unique);
create table public.brands(id uuid primary key default gen_random_uuid(),name text not null unique);
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,brand_id uuid references public.brands(id),category_id uuid references public.categories(id),description text,image_url text,created_at timestamptz not null default now());
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),name text not null,quantity numeric(14,4),unit text,attributes jsonb not null default '{}'::jsonb);
create table public.product_identifiers(id uuid primary key default gen_random_uuid(),variant_id uuid not null references public.product_variants(id),kind text not null,value text not null,verified boolean not null default false,unique(kind,value,variant_id));
create table public.retailer_products(id uuid primary key default gen_random_uuid(),retailer_id uuid not null references public.retailers(id),source_id uuid not null references public.data_sources(id),external_id text not null,variant_id uuid references public.product_variants(id),source_name text not null,source_url text,last_seen_at timestamptz,unique(source_id,external_id));
create table public.store_offers(id uuid primary key default gen_random_uuid(),retailer_product_id uuid not null references public.retailer_products(id),store_id uuid not null references public.retailer_stores(id),regular_price numeric(12,2) check(regular_price>=0),sale_price numeric(12,2) check(sale_price>=0),currency char(3) not null default 'CAD',observed_at timestamptz not null,valid_until timestamptz,member_only boolean not null default false,status text not null default 'active' check(status in ('active','stale','expired','withdrawn')),unique(retailer_product_id,store_id));
create table public.import_jobs(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.data_sources(id),status text not null default 'queued',started_at timestamptz,finished_at timestamptz,received integer not null default 0,accepted integer not null default 0,rejected integer not null default 0,error_summary text);
create table public.price_history(id bigint generated always as identity primary key,retailer_product_id uuid not null references public.retailer_products(id),store_id uuid not null references public.retailer_stores(id),source_id uuid not null references public.data_sources(id),import_job_id uuid references public.import_jobs(id),regular_price numeric(12,2),sale_price numeric(12,2),currency char(3) not null default 'CAD',observed_at timestamptz not null,created_at timestamptz not null default now());
create table public.shopping_lists(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null default 'My list',created_at timestamptz not null default now());
create table public.shopping_list_items(id uuid primary key default gen_random_uuid(),list_id uuid not null references public.shopping_lists(id) on delete cascade,variant_id uuid references public.product_variants(id),label text not null,quantity numeric(10,2) not null default 1 check(quantity>0),created_at timestamptz not null default now());
create table public.price_alerts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,variant_id uuid not null references public.product_variants(id),target_price numeric(12,2) not null check(target_price>=0),active boolean not null default true,created_at timestamptz not null default now());
create index products_name_trgm on public.products using gin(name gin_trgm_ops);
create index offers_store_observed on public.store_offers(store_id,observed_at desc);
create index history_product_time on public.price_history(retailer_product_id,observed_at desc);
create index list_user on public.shopping_lists(user_id);
create index alert_user on public.price_alerts(user_id);
alter table public.retailers enable row level security;
alter table public.retailer_stores enable row level security;
alter table public.data_sources enable row level security;
alter table public.categories enable row level security;
alter table public.brands enable row level security;
alter table public.products enable row level security;
alter table public.product_variants enable row level security;
alter table public.product_identifiers enable row level security;
alter table public.retailer_products enable row level security;
alter table public.store_offers enable row level security;
alter table public.import_jobs enable row level security;
alter table public.price_history enable row level security;
alter table public.shopping_lists enable row level security;
alter table public.shopping_list_items enable row level security;
alter table public.price_alerts enable row level security;
create policy public_retailers_read on public.retailers for select to anon,authenticated using(status='active');
create policy public_stores_read on public.retailer_stores for select to anon,authenticated using(active and exists(select 1 from public.retailers r where r.id=retailer_id and r.status='active'));
create policy public_categories_read on public.categories for select to anon,authenticated using(true);
create policy public_brands_read on public.brands for select to anon,authenticated using(true);
create policy public_products_read on public.products for select to anon,authenticated using(true);
create policy public_variants_read on public.product_variants for select to anon,authenticated using(true);
create policy public_identifiers_read on public.product_identifiers for select to anon,authenticated using(verified);
create policy public_retailer_products_read on public.retailer_products for select to anon,authenticated using(exists(select 1 from public.data_sources d where d.id=source_id and d.authorization_status='authorized' and d.allowed_redistribution and (d.license_expires_at is null or d.license_expires_at>now())));
create policy public_offers_read on public.store_offers for select to anon,authenticated using(status='active' and observed_at>now()-interval '48 hours' and (valid_until is null or valid_until>now()) and exists(select 1 from public.retailer_products rp join public.data_sources d on d.id=rp.source_id where rp.id=retailer_product_id and d.authorization_status='authorized' and d.allowed_redistribution and (d.license_expires_at is null or d.license_expires_at>now())));
create policy own_lists on public.shopping_lists for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy own_items on public.shopping_list_items for all to authenticated using(exists(select 1 from public.shopping_lists l where l.id=list_id and l.user_id=(select auth.uid()))) with check(exists(select 1 from public.shopping_lists l where l.id=list_id and l.user_id=(select auth.uid())));
create policy own_alerts on public.price_alerts for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
-- No client write access to catalog, offers, sources, imports or price history. Ingestion must use privileged server-side workers.
